          '法典在多大程度上被真正执行，学界至今争论：现存泥板判决书很少直接引用它的条文，它更像一份王室正义宣言加一部法律教科书。但争议本身不重要——重要的是它立起了「成文、公开、按条文量刑」这个模板：判决可以争论，规则必须先摆出来。',
