          '文字的对照版几乎同时存在：孟元老在北宋亡后写《东京梦华录》追忆汴京，写「八荒争凑，万国咸通」，写夜市至三更、早市又开张，写州桥夜市的灯火香气。画与书互为注脚——一图一文，从眼睛和耳朵两个方向，把一座已经消失的城市钉进了历史。',
