          '国内市场起初对青花并不热心：宋代以来士大夫尚素雅，单色釉才是雅器，青花的浓艳甚至被视为俗气。它的翻身要等到明代——郑和七下西洋（1405—1433），宝船上压舱的大宗货物就是青花瓷，官窑青花从此成为国家名片与外交礼品。',
          '欧洲人随后排队入场：十六世纪起葡萄牙人直航亚洲，「克拉克瓷」专供外销订制；青花在欧洲被称作「白金」，萨克森选帝侯奥古斯都二世曾用六百名龙骑兵换来一百五十一件中国瓷器——士兵换瓷器的交易，放在任何时代都算得上疯狂，也说明它在当时的欧洲是什么身价。',
