          '古卷的内容分三类：约二百二十份希伯来圣经抄本——除《以斯帖记》外，旧约各卷都有残卷出土；大批次经、伪经与此前闻所未闻的文献；还有社团自己的规则文书，《会规手册》《战争卷》《感恩诗篇》，记录一个末世社团如何生活、如何纪律、如何等待最后决战。',
          '头号冲击在版本学：此前最古老的完整希伯来圣经抄本是公元十世纪的阿勒颇抄本，古卷一下把证据链提前了一千多年。比对结果令人震动——《大以赛亚卷》与今日通行的马所拉文本差异极小，主要是个别拼写与笔误。一千年的手工传抄，几乎零漂移，这在没有印刷术的时代近乎奇迹。',
