          '语言构成同样说明问题：希伯来文为主，兼有亚兰文与希腊文，是一个多语社会的文字样本，抄写者在不同语言之间切换自如。抄经的人清楚自己在为谁抄写——他们相信末日将近，这些字是写给最后一代读者的，每一个字母都不敢潦草。末日没有来，读者来晚了两千年，但终究来了。',
