          '那些把经文封进陶罐的人，以为自己是在为末日做最后的准备；结果末日没有来，罗马军团换了旗帜，帝国换了一茬又一茬，字却原封不动地活了两千年。他们等来的不是审判，是读者——两千年后的深夜，还有人就着屏幕的光，逐行放大他们写下的每一笔。这大概是写在任何经典边上，最合适的一句批注。',
