          '圣索菲亚的诞生源于一场灾难。532 年，君士坦丁堡爆发尼卡暴动，半个月的骚乱死者数以万计，旧教堂化为焦土。查士丁尼在血腥平乱之后决定原地重建——而且要建成一座让全世界闭嘴的建筑：压得住乱局的人，也要压得住天际线。',
