      '1900 年 6 月 22 日，莫高窟。道士王圆箓雇人清理第 16 窟的积沙，墙壁裂开一道缝——灯芯探进去，火光照出满满一屋子码放的经卷，一直堆到房顶。这个后来编为第 17 窟的小密室，封存着从 4 世纪到 11 世纪的手写文书、绢画与法器约五万件。一门世界显学，从一道墙缝开始。而推开这道缝的王圆箓，只是湖北来的退伍兵勇、半路出家的道士。',
