          '谁封的洞？避难说（防西夏兵燹）、废弃说（敬惜字纸）与书库说各执一词，封洞时间约在 11 世纪初，谜底至今未解。但正是这次封存，让长安、洛阳毁于战火的唐代文献，在西北一隅留了一个备份——历史的讽刺在于：一次仓促的丢弃，胜过一切精心的保存。',
