          '痛心之余，学问本身长成了参天大树：罗振玉、王国维以来，「敦煌学」横跨历史、宗教、语言、艺术，成为国际显学。近年中国推动「数字敦煌」，全球藏品的影像陆续上网免费公开——散落天涯的经卷，在一百多年后于云端重新团聚。',
