          '有意思的是，图上已有真实信息的萌芽：耶路撒冷、罗马、巴黎的位置大体可用；不列颠岛画得出乎意料地细，标出二十余座城镇，包括作者家乡。地图对「近处」忠实，对「远处」想象——这与今天的信息生态惊人地一致：我们对身边无所不知，对远方一无所知。',
