          '分歧之外有共识：宝船是当时世界最大的木构船只，采用水密隔舱与多重船板，抗沉性远超同期欧洲船；船队主力其实不是宝船，而是载货的马船、战船与粮船——一次下西洋出动两万七千余人、船两百余艘，是成建制的远洋体系，不是冒险家的孤帆。',
