          '技术随之退场：到明末，中国远洋木船的尺度再未回到宝船的水平，葡萄牙人的卡拉克帆船成了印度洋的新主人。一整套成熟体系在鼎盛时被主动雪藏——这在世界航海史上是孤例：不是技术做不到，而是国家决定不再做了。',
