          '第二棒是希腊与伊斯兰世界。星盘发明于希腊化时代，托勒密专门写过它的原理；此后数百年它是伊斯兰世界最精致的仪器——存世的中世纪星盘大多出自巴格达、开罗与安达卢斯的工匠，刻着阿拉伯文铭文。欧洲人后来仿制的星盘上，好几个术语都带着阿拉伯语的「al-」词头。',
          '第三棒是欧洲的整理。1406 年，托勒密《地理学》的拉丁译本问世，经纬网制图学重新进入欧洲；罗盘方位线+经纬网+星盘测天，拼成完整的航海仪器链。大航海是一场接力赛的最后一棒——这一点，工具上的文字比任何史书都诚实。',
