          '代价积累到 1707 年：英国舰队在锡利群岛因定位失误触礁，四艘战舰沉没，约两千名水手丧生。英国议会次年通过《经度法案》，悬赏两万英镑征集解决方案——相当于今天的上千万英镑。1761 年，木匠出身的钟表匠哈里森造出航海天文钟 H4，远航数月误差不足一秒，经度难题就此终结。',
