          '16 世纪起，浮雕铜板成批生产，钉在王宫庭院的木柱上，如同一条金属的编年史长廊：奥巴的出巡与册封、宫廷武人、仪式场面，乃至来贸易的葡萄牙人——最早一批与欧洲人打交道的西非历史，是被非洲工匠自己记录下来的。',
          '这一点值得强调：贝宁青铜器不是「被欧洲发现的非洲艺术」，而是一个拥有自身史官传统的宫廷，主动把历史铸进了铜里。欧洲人只是晚到了几百年。',
