          '20 世纪初，德国民族学家费利克斯·冯·卢尚大规模收藏贝宁铜器，他留下的评价被反复引用（译述）：即使以欧洲最先进的工艺与审美标准衡量，这些作品也称得上惊人——他直接拿它们与文艺复兴金工的顶尖作品相比。这句评价刺破的，正是当时「非洲无文明艺术」的欧洲偏见。',
          '而偏见破产得并不彻底：此后半个多世纪，这些铜器在世界博物馆里被当作「民族志标本」陈列，而非当作艺术史正典。名分与实物之间，隔着一整个殖民时代。',
