          '接着是系统性的运走：数千件铜器、象牙雕刻被士兵与军官装船，运抵伦敦后公开拍卖，部分收益按官方记录用于抵充远征开支——抢劫与报销，走的是同一条账目。大英博物馆、柏林民族学博物馆等机构由此成为最大藏家。',
          '「惩罚远征」（Punitive Expedition）这个词本身值得记下：殖民史上，暴力常被注册成执法。文物一旦进入这个流程，从战利品变成「馆藏」，再加一层「文化遗产」，来路就被层层包装住了。',
