          '转折发生在 2020 年代。2022 年，德国与尼日利亚签署联合宣言，承诺归还所藏千余件贝宁铜器，当年年底首批移交；史密森尼学会宣布归还 29 件；伦敦与牛津等机构则以出借与共管方案应对。大英博物馆的处境最尴尬——1963 年的《大英博物馆法》禁止馆方转让所有权，馆方只能谈租借。法律条文与历史欠账，第一次正面相撞。',
          '归还的不只是物件：尼日利亚还在推进贝宁城新的西非艺术博物馆项目，让文物回家后「有处可去」。文物谈判桌的形状，正在改变博物馆世界的规则。',
