          '现藏分布是这份证词的一部分：大英博物馆、柏林民族学博物馆藏量最大，尼日利亚国家博物馆与贝宁城宫廷博物馆持有历年归还与留存的部分。收藏地图本身就是一张殖民史地图。',
          '文物回家的路有多长，正义的进度就有多慢——但方向已经确定。这批铜器最深的讽刺与最深的希望是同一件事：它们铸下的是宫廷的历史，如今却在改写博物馆的历史。',
