          '她们没有蓝图可抄，要自己发明调试方法、分解计算流程、组织机器的资源——现代编程的诸多思想雏形，是在接线板上试出来的。但这六个人的贡献被埋没了几十年：报道与合影里，她们常被当成站在机器旁的「模型」，直到半个世纪后才被正式承认为第一代程序员。',
          '技术上，ENIAC 还差最后一步：程序仍靠外部设置，机器本身不存程序。1945 年冯·诺伊曼加入后续设计，「存储程序」概念确立——同一台机器，换一套程序就能换一份工作。「通用」二字，自此才名副其实。',
