    summary: '世宗大王创制的拼音文字，世界上设计最科学的文字之一。',
    paragraphs: [
      '「国之语音，异乎中国，与文字不相流通。故愚民有所欲言，而终不得伸其情者多矣。」1446年，一位朝鲜国王把自己的造字动机写进诏书序言，白纸黑字：百姓说不出的苦，是因为字不属于他们。他叫李裪，庙号世宗，后世称世宗大王——人类历史上极少数由君主亲自主持、为平民造字的案例，就诞生在他的王宫里。',
    ],
    sections: [
      {
        heading: '它是什么：28个字母的国家工程',
        paragraphs: [
          '1443年，世宗召集学者创制「训民正音」——教百姓正确的发音，1446年正式颁行。方案含28个字母（今天韩文用24个），可拼出朝鲜语的一切音节。从立项到颁行只有三年：这是一项帝王直接牵头、学者实测发音的国家级语言工程。据载，国王反复让人试读试写，把不便认、不便写的方案一次次打回重造——工程的主审官，就是日后使用者最多的那个人。',
          '设计近乎一篇语音学论文：辅音字母模仿发音器官——舌根音「ㄱ」画舌根堵喉的样子，「ㅁ」描嘴唇，「ㅅ」描齿，「ㅇ」描喉；元音取象天圆、地平、人立三点。加一笔变送气（ㄱ→ㅋ），字母叠写变紧音——一根笔画，就是一条语音规则。字母拼成音节块，方块里藏着一套拼音系统。',
          '它的另一重高明在「可扩展」：表音系统预留了变化空间，后来传入的外来新词新音，也大多能按原有规则拼出；从活字印刷到手机键盘，这套五百多年前的方案几乎不需要修改。一件文物最罕见的状态是仍在服役——谚文从纸页一路工作到了触屏。',
        ],
      },
      {
        heading: '功能与主人：为不识字的人写字',
        paragraphs: [
          '颁行后它先服务起王朝自己忽视的人群：女性读佛经、写家信，庶民记账、写状纸，乐工用谚文记下宫廷乐谱。汉字仍是科举与官方的正统，谚文的定位本是「注音工具」——但识字的大门，实实在在从士大夫的书房推到了平民的门口。',
          '士大夫的抵制同样激烈：1444年，集贤殿副提学崔万理上疏痛斥，认为另造文字将动摇以汉字经典为根干的礼制秩序。世宗没有收回成命，却也无力让它登堂入室——此后数百年，谚文顶着「俗字」之名在民间顽强地活着。',
        ],
      },
      {
        heading: '流传：从压制到国字',
        paragraphs: [
          '转机迟到得惊人：1894年甲午更张，公文明令韩汉并用；日据时期殖民当局反复压制朝鲜语教育，1942年朝鲜语学会的学者甚至被集体逮捕——一部文字的生命力，用坐牢来计量。1948年建国后，南北双方不约而同把谚文定为国字：被骂了几百年的「俗字」，成了民族身份的承重墙。',
          '今天韩国成人识字率接近100%，常被归功于谚文的上手速度——普通人数小时即可拼读。1997年，《训民正音》解例本入选联合国教科文组织世界记忆遗产；每年10月9日是法定假日「韩文日」。一个字母表拥有自己的节日，全世界屈指可数。近年偶有恢复汉字混写的讨论，每次都激起轩然大波——这反而证明：文字之争，从来不只是技术之争。',
        ],
      },
      {
        heading: '意义：一次造字的哲学',
        paragraphs: [
          '谚文真正罕见的不是「科学」，而是立场：它假定所有人——无论贵贱、无论性别——都配拥有读写能力。这与同时代「文字是士绅装饰」的氛围完全相反。世宗在序言里说自己「为此悯然」，悯的不是文脉，是人。',
          '语言学界给它极高的评价，有学者称其为世上最科学的文字系统之一。汉字文化圈各国都走过文字改革的窄门，只有朝鲜半岛走到了拼音化终点。六百年前那位国王的判断至今成立：让所有人写得出自己说的话，是一个国家最大的善政之一。',
        ],
      },
    ],
    quote: '国之语音，异乎中国，与文字不相流通。故愚民有所欲言，而终不得伸其情者多矣。',
