          '木构的智慧同样惊人：全城以榫卯与斗拱连接，不靠钉子的刚性固定——地震来临，节点以微形变卸力。太和殿历史上多次毁于雷火，现存建筑为1695年康熙年间重建，殿内72根大柱撑起现存中国最大的木构大殿。匠作是国家的最高技术部门，这座城就是他们的卷面。',
          '建造者还给这座城留了后手：单体建筑全部标准化、模块化，梁柱斗拱按规制预制，烧毁了可以照原样重修。明亡清兴，宫殿没有推倒重来——李自成撤离时放火烧掉几座大殿，清代一一复原，连匾额的名字都懒得换。这种「可复制的永恒」，正是中国官式建筑的终极野心。',
