          '1988 年，杰内旧城区整体列入世界遗产。旅行者常被一句话击中：这不是博物馆里的遗迹，而是每天做礼拜的清真寺——泥墙上的每一根棕榈梁、每一道裂缝，都还处在使用中。它的历史不在过去时。',
