          '纳斯卡线条其实一直在脚下——谷地居民早就见过这些「路」。1927 年，秘鲁考古学家托里维奥·梅希亚·谢斯佩首先指出它们是刻意制作的地画；真正看清全貌要等航空时代：1930 年代商业航线飞过秘鲁南部，飞行员与乘客发现荒漠上盘着巨大的动物——在地面上是乱沟，升上天空是画。',
