          '目前更有力的解释是朝圣与游行：许多线条通向地画中央的土丘与祭祀点，人们沿线条行走、进入图形内部完成仪式；2024 年，人工智能辅助勘查找出约三百幅此前未被记录的小地画，多画在山坡上、贴近村落——它们是给人走近看的，不全是给天空的。或许两说并存：日常的游行属人，整片荒原的构图属神。',
