    id: 'chichen-itza',
    category: 'artifact',
    name: '奇琴伊察',
    foreign: 'Chichen Itza',
image: {
      src: '/images/chichen-itza.jpg',
      page: 'https://commons.wikimedia.org/wiki/File:Chichen_Itza_3.jpg',
      author: 'Daniel Schwen',
      license: 'CC BY-SA 4.0',
    },
    region: 'americas',
    year: 600,
    range: [600, 1200],
    kicker: '会报时的金字塔',
    summary: '玛雅的羽蛇神之城，春分时阳光在阶梯上游出巨蛇。',
    paragraphs: [
      '每年 3 月 21 日前后的尤卡坦半岛午后，卡斯蒂略金字塔的北面阶梯会准时上演一幕光剧：夕阳把九层塔体的棱角投在护栏上，一串锯齿状的影子缓缓蠕动、起伏，一直爬到塔基那颗石雕蛇头跟前——光影与石头，在春分的下午接头。九百多年前，玛雅人把日历、神庙与天文台叠成了一座城，名字叫奇琴伊察：伊察人的井口。',
    ],
    sections: [
      {
        heading: '它是什么：井口上的城',
        paragraphs: [
          '奇琴伊察建在尤卡坦北部干旱的石灰岩台地上：地表无河无溪，全城命脉是天然溶井「塞诺特」——「奇琴伊察」意为「伊察人的井口」。玛雅人约在公元 6 世纪前后在此立城，9 世纪后势力大盛，融入来自中墨西哥的托尔特克风格，成为半岛最强的宗教与政治中心。',
          '1841 年，美国旅行家斯蒂芬斯与英国画家卡瑟伍德骑马穿过丛林抵达此地，两卷《尤卡坦旅行记》与上百张精确版画让玛雅废墟第一次进入西方视野。1920 年代起墨西哥政府开始系统修复；1988 年列入世界遗产，2007 年入选新七大奇迹。',
        ],
      },
      {
        heading: '工艺与细节：一座会算日历的金字塔',
        paragraphs: [
          '卡斯蒂略金字塔通高约 30 米，九层塔体四面各设台阶 91 级，加上塔顶神庙平台恰好 365——整座建筑就是一块立起来的历法石。玛雅工匠让数字、方位与仪式共用一套几何：塔身四面严格对准正方向，春分秋分的蛇影只出现在北阶，年年准时，误差以天计。',
          '细节里全是心机：在塔下拍手，回声会变成一声鸟鸣，接近中美洲凤尾绿咬鹃的啼叫——声学研究证实这并非巧合。塔内还叠着一座更早的金字塔，考古学家在内部分凿出通道，找到一间藏着红色美洲豹浮雕与豹形宝座的小室。城中的卡拉科尔天文台，窗户对准金星运行的最北与最南方位——金星历正是玛雅人最自负的天文学。',
        ],
      },
      {
        heading: '功能与主人：羽蛇神与圣井的祭司',
        paragraphs: [
          '9 世纪后的奇琴伊察供奉羽蛇神库库尔坎——中墨西哥的克察尔科亚特尔在此落地：蛇纹浮雕、查克莫尔像与骷髅台铺满全城。中美洲最大的球场也在这里：168 米长、70 米宽，两队以胯部击打实心橡胶球，把球送进高悬的石环——比赛同时是仪式，仪式同时是生死。',
          '城北的「圣井」直径约六十米，是水源兼神谕所。1566 年前后，兰达主教在《尤卡坦风物志》里记下玛雅遗俗：旱灾之年，人们向井中投下活人祈求神谕。1904 年起美国人汤普森疏浚圣井，捞出人骨、玉器与金盘——记载与考古在此对上号；那批文物漂洋过海半个多世纪后，大多追索归还墨西哥。',
        ],
      },
      {
        heading: '流传命运：丛林、修复与争论',
        paragraphs: [
          '约 1200 年后奇琴伊察衰落，权力移往玛雅潘；西班牙人 16 世纪到达时，大城已在丛林里空置数百年。20 世纪的修复带着时代局限：墨西哥考古队把金字塔与球场修成今日的整齐面貌，未发掘的数百座建筑仍埋在林下——游客看到的，是一座被选择过的城。',
          '学界至今争论「托尔特克化」的成色：9 世纪后中墨西哥风格的涌入，究竟是征服、移民还是风尚互鉴？托尔特克本身早已面目模糊，一座边界之城恰好卡在两大传统的疑云之间。争论没有标准答案，但答案也不太要紧了：石头站在那里，比任何论点都持久。',
        ],
      },
      {
        heading: '意义：把天文写进城市的人',
        paragraphs: [
          '奇琴伊察的真正遗产是「建筑即仪器」的观念：历法、农耕周期、王权仪式与神谕，全部浇筑进石头的朝向与数目里。玛雅人没有金属工具，没有轮车，靠黑曜石刀具与人海，把天文观测的精度做进了一场每年准时上演的光影演出。',
          '今天每年春分，数万人挤在北阶下看蛇影爬完最后一级台阶，欢呼声与快门声盖过风——一场九百年前的光影演出，仍在准点上演，而且场场满座。奇琴伊察提醒现代人：所谓奇迹，常常只是前人把一种极为耐心的时间感，砌进了石头。',
        ],
      },
    ],
    quote: '旱灾之年，他们向井中投下活人，祈求神明给出答案。',
