          '点睛是最后一道、也是最重要的一道工序：眼白用珊瑚片，瞳孔用黑曜石圆片，嵌入眼窝的仪式一旦完成，祖先之力便注入石像——没有眼睛的摩艾只是石头，有眼睛的摩艾是活着的祖先。1978 年，考古学家在阿胡瑙瑙的一处眼窝里找到了保存完好的珊瑚眼片，证实了口传与浮雕的记载：所有石像，本来都有一双眼睛。',
