          '十八世纪的访客们看到的，已是战乱与饥荒的余烬。真正的灭顶之灾在 1862 年：秘鲁奴隶船掳走近半数岛民做苦力，获释幸存者又把天花带回岛上，1877 年全岛人口只剩约一百一十人——拉帕努伊文明没有死于推倒石像的内战，却差点死于外来的奴隶贸易。1888 年智利并岛，此后几十年岛民被圈禁在村镇里，语言与仪式一度濒危。',
          '复活从二十世纪中叶开始：1955 年海尔达尔考察队重新唤起世界关注；1960 年智利大地震引发的海啸，把汤加里基平台的十五尊摩艾整个掀进内陆；1990 年代，在日本企业捐助的起重机协助下，十五尊石像被逐一扶正复位——1960 年推倒它们的是太平洋，1996 年扶起它们的是一台日本吊车，历史有时荒诞得刚刚好。今天约五十尊摩艾重新站立，其中少数获准恢复了眼睛。',
