          '二十世纪末，贾雷德·戴蒙德把它写进《崩溃》，摩艾从此成了「文明自杀」的世界级警示图标；但近年的考古与古植物学研究给出更复杂的版本：棕榈消失有老鼠啃食种子的份，岛上人口在接触前未必崩溃，真正把社会打碎的更是奴隶船与瘟疫。教训没有变，责任人却换了——对一个文明的死亡判决书，签发之前要多查几遍。这是摩艾教的最后一课。',
