          '它也是提醒：史前不等于蒙昧。与它大体同时，尼罗河畔垒起金字塔，印度河谷规划出整齐的城市——青铜时代之前的人类，早已是大规模协作的物种。巨石阵在平原上站了近五千年，像一句没有字母的宣言：我们曾这样组织过自己。',
