          '真正的跃迁发生在北宋：人工磁化取代了天然磁石。曾公亮《武经总要》（1044）记「指南鱼」——剪铁为鱼、烧红淬磁，浮于水面；稍后沈括记下更简便的「磁石磨针」法，并列出四种装置方式：水浮、指爪、碗唇、缕悬——他评价缕悬「最善」。一根缝衣针，取代了整块磁石。',
