          '针路簿是航海家族的圣典，在闽粤船民间口耳相传数百年，一字一句都是拿人命换来的航程。指南针没有淘汰老水手，它做的是另一件事：把老水手的私人记忆，变成可以复制、可以传授、可以跨船检验的路线图——远洋技艺第一次被降维成可教的操作。',
