          '沈括那个「微偏东」的观察，四百年后在欧洲长成地磁学：吉尔伯特 1600 年著《论磁》，推断地球本身就是一块大磁石；再往后，磁倾角与磁暴的测量又把线索指向地核与太阳风。一根针牵出的学科至今仍在生长——司南的勺柄，指向的从来不只是南方。',
