          '它是「叙事刺绣」而非真正的挂毯——羊毛线绣在亚麻底布上。上下边缘填满狮子、龙、农人与一些暧昧的边饰，常被解读为对主叙事的讽刺注脚。学界通说：设计者是教士，绣工是英格兰女工——征服者用被征服者的手，绣自己的胜利。',
