          '铭文的主人公是大流士一世。前 522 年，波斯宫廷剧变：冈比西斯二世远征埃及途中暴亡，祭司高墨达冒充亡弟巴尔迪亚夺位七个月，大流士与六名贵族刺杀篡位者、夺回王权。帝国瞬间四分五裂，埃兰、巴比伦、米底、波斯各省纷纷称王——大流士用一年打了十九场战役、擒获九位叛王，把帝国重新缝合起来。',
          '这份「年度述职报告」被以最高规格发布：崖壁被人工削平，浮雕上大流士张弓而立，脚踩高墨达，身后九王鱼贯被缚，头顶是波斯主神阿胡拉·马兹达的光环；三段铭文用古波斯语、埃兰语、阿卡德语（巴比伦语）讲述同一段历史，各语言合计约五千行。以当时的技术，把这么多字刻上百米绝壁，本身就是一场国力秀。',
