          '三种文字的排列各有用意：古波斯语是新造的字母式楔形文字（为王的母语专造），居中居于正位；埃兰语是帝国行政的老牌语言；阿卡德语面向两河流域的国际读者。同一份内容的三个版本并排而立——大流士本意是让全帝国读懂自己，无意间却为后世留下了一份自带译文的对照文本。',
