          '今天的游客站在贝希斯敦崖下的公路边，抬头看那幅悬在百米高处的浮雕。罗塞塔石碑靠一通法令的三种文字打开象形文字，贝希斯敦靠一通胜利公告的三种文字打开楔形文字——人类破解失落的语言，靠的从来不是天才的灵光，而是有人恰好把同一句话说给了两个时代听。',
