          '法贝热的看家本领是「惊喜结构」：每枚蛋都是俄罗斯套娃式的机关——外壳珐琅彩绘，中壳旋转开启，内里藏着微缩奇观，最深处往往是价值连城的小件。为了一枚蛋，工匠可能耗上一年：掐丝珐琅、半透明珐琅、宝石镶嵌、黄金机械，作坊几乎把俄国金工的全部绝技压缩进掌心大小。',
          '作坊本身是个小型帝国：鼎盛期工匠约五百人，各分金银、珐琅、细工等专坊，卡尔·法贝热只在最后的惊喜环节亲自拍板。他有一条流传甚广的经营格言：东西贵不贵他不在乎，工艺必须无可挑剔——沙皇的订单要的从来不是价格，是「让皇后惊叹」这件事本身。',
