          '古腾堡的核心配方有三样：铅锡锑合金的活字（熔点低、耐压、字迹清晰）、改良的印刷油墨（亚麻油加烟灰，黏度专为金属版调制），以及改造的螺旋压印机——葡萄酒压榨机的结构，第一次压在了纸上。每一项单看都不神奇，合在一起，是把「复制文本」从手工业变成了制造业。',
          '排版本身是流水线的雏形：排字工从字盘里拣字组版，印完拆版回炉，字可反复使用——「活」字的价值正在于此。校对、压印、装订分段协作，作坊同时开动数台印刷机。据估算，完成一百八十部圣经约动用了六名排字工同时作业数年，这已是十五世纪能组织起来的最大规模出版工程。',
