          '对抄经行业，活字的胜利近乎降维打击：一个抄经房年产量不过几部大书，一家印坊一年可出上千册。到 1500 年，欧洲已有二百五十多个城市拥有印刷所，累计印书约两千万册——此前一千年欧洲手抄书存量加起来也没这么多。知识的价格曲线被斩断，识字人口的扩张从此失去天花板。',
          '古腾堡的余生黯淡：败诉后他靠美因茨大主教赐予的宫廷年金度日，1468 年在相对贫困中去世，葬礼由同会教友料理。他的名字后来被印在每一本讲述印刷术的书上，但他本人生前没有从任何一部圣经的利润中分得一杯羹——他是历史上极少数以本人名字命名整场革命、却未从革命中获利的发明家。',
          '直到 1900 年代，美因茨才为这位游子立像建馆；今天古腾堡博物馆就坐落在当年作坊的同一条街上。历史对失败者的追认常常迟到，但这次利息惊人——他被追认为「新闻与出版之父」，他的圣经被称为「世界上最著名的书」。产业归了债主，荣誉归了发明者，五百年后看，后者更值钱。',
