          '古腾堡圣经在文化史里的地位早已超出书籍：它是「信息成本骤降」的界碑。图书价格斩断、方言出版兴起、作者-读者关系成型——欧洲的宗教改革、文艺复兴扩散与科学共同体，全都踩在这块新地基上。历史学家习惯说印刷术是现代性的推土机，而这部圣经，就是推土机交付的第一件作品。',
          '今天，大英图书馆把它的藏本整册数字化，任何人在手机上都能翻阅每一页四十二行的哥特字——五百年前一百八十部、锁在修道院与王宫里的圣物，如今同时向八十亿人开放。古腾堡若能看到这一幕应该欣慰：他毕生想做的事，无非是让书变得更便宜、离人更近。这道题，互联网替他答完了。',
