          '诺斯替主义（Gnosis，灵知）主张救恩靠秘传的真知而非信仰与善功：物质世界是无知的造物神造出的牢笼，人心里沉睡的神圣火花要靠知识唤醒，才能穿过层层天界回归真神。这套世界观与后来定型的正教几乎处处相反：不认肉身复活，淡薄旧约造物主，把创世读成一场事故。早期教会把它定为头号异端，注定它要在地下消失。',
