          '专门执掌奇普的官员叫基普卡玛尤克（「结绳的掌管者」），由帝国培训、终身任职，村社与王庭各置一套；他们核对仓储、上报人口、追缴欠税，帝国庞大的再分配经济就靠这群「绳子会计」维持精度。西班牙编年史家记载，结绳官能不看任何文字辅助，当众报出数年前某村的劳役数字——这是一种以记忆为后盾的精算职业。',
