          '灯的身份写在器身上：九处六十五字铭文，其中「长信」二字指明它曾供奉于长信宫——汉文帝皇后窦氏（著名的窦太后）的居所。窦绾恰是窦氏族人，学者推测这盏灯是长信宫赐予窦家的礼物，随女主人入葬。',
