          '地球是圆的，这在 1492 年不是新鲜知识——亚里士多德早已论证，托勒密《地理学》1406 年的拉丁译本让测算方法重新流行。真正新鲜的是：这一知识第一次从学者的书桌走向商人的账房，变成可以被「握住」的商品。纽伦堡——帝国自由市、天文仪器与地理出版的重镇——恰好站在这个拐点上。',
          '马丁·贝海姆是标准的文艺复兴式跨界人物：纽伦堡商人之子，跑过安特卫普与里斯本的生意，1480 年代定居葡萄牙所属的亚速尔群岛法伊尔岛，卷入葡萄牙的大西洋开拓事业，自述曾为葡萄牙宫廷的海事咨询出力。大航海的传闻、测绘与野心，他是第一批同时握有常识与关系网的人。',
          '1491 年他回到家乡，纽伦堡市政会热情接待，并委托制作一件能展示「新知识」的球形仪器。1492 年春动工，画家格洛肯登负责彩绘。谁也没料到，球完工的同一季，大西洋对岸撞进一整块洲。',
