          '球面上，欧洲、亚洲、非洲构成全部大陆；非洲西岸的轮廓采纳了葡萄牙人刚刚探明的成果——迪亚士 1488 年绕过的好望角赫然在列。亚洲部分则全盘接续马可·波罗与托斯卡内利的想象：中国海岸向东不远就是日本（Cipangu），香料群岛铺满南方。大西洋两岸之间，只隔着一望无际的、可以横渡的蓝。',
          '地图上还郑重标注了那些并不存在的岛屿：圣布伦丹岛、安提利亚等中世纪传说之岛，与真实港口并列。它如实保存了那个时代的认知结构：新测量的精确与旧传说的执念，共存在同一个球面上。',
