          '背景是拜占庭的圣化运动：自君士坦丁之母海伦娜寻得「真十字架」的传说起，帝国把圣地逐一立碑建堂。地图上的每个圣所都对应一座真实建筑——它既是导航，也是帝国「管理圣地」的清单，把空间钉进了教义。',
