          '蒂申多夫的两次获得成就了它，也埋下争议：1844 年他取走四十三叶（后藏于莱比锡），1859 年他借沙皇亚历山大二世的支持取得三百四十六叶献呈沙皇，藏于圣彼得堡。修道院一方长期持另一版本叙事：那些叶是「借阅」而非「赠予」。真相纠缠在十九世纪东方学的权力关系里，至今两边各执一词。',
          '1933 年，苏联政府把圣彼得堡藏叶作价十万英镑卖给大英博物馆——为筹资，英国发起了公众募捐。此后抄本分居四地：大英图书馆藏主体，莱比锡大学图书馆、圣凯瑟琳修道院与俄罗斯国家图书馆各藏残叶。一部圣经抄本，见证了从沙俄到苏联、从帝国到民族国家的全部辗转。',
          '2009 年，四家收藏机构完成数字化联网，抄本的全部页面与层叠校改第一次在网上「合璧」——物理上被拆散一百六十多年的书，在云端重新装订。修道院 1975 年又在密室里发现新的残叶，学界至今仍在把新碎片缀回这部四世纪的大书：它的校改史，还没有写完。',
