          '它的不寻常在于「知识密度」：金片的排列不是装饰想象，而是可以核对的天象。盘面经历过多期改造——早期只有日月星；中期在两侧加镶两道金弧，每弧张角八十二点七度，恰好等于中欧纬度夏至与冬至日升日落之间的地平张角：这是一台立体的太阳历装置。晚期又在下缘补上第三道金弧，多解读为太阳船，连彼岸信仰都有了。',
