          '她现藏维也纳自然历史博物馆，是镇馆之宝：展柜前常年的围观人群，与她第一次被从黄土里翻出来时围观的工人们，构成了同一种姿态——人类围观自己的来处。2008 年出土百年纪念时，奥地利为她办了专题大展，全球研究者把百年研究史重梳了一遍：结论仍开放，方法已换了几代。',
          '贡布里希《艺术的故事》的开篇名句常被用在她身上：实际上没有艺术这种东西，只有艺术家而已。她的作者无名，动机成谜，作品却穿过两万八千年抵达我们掌心——艺术史的证明不必等待签名：只要有人雕过、有人看过、有人继续看，那双手就没有消失。',
