          '罗马人叫它「弗拉维圆形剧场」（Amphitheatrum Flavium）；「斗兽场」（Colosseum）的俗称来自旁边竖立的尼禄巨像（Colossus）——皇帝的铜像没了，绰号却留给了建筑。今天意大利五分欧硬币背面印的，就是这道轮廓。',
