          '狮子门建于迈锡尼全盛期（约前 1250 年），是卫城东南方向的正式入口：两块巨大的独石竖立为门柱，上横一块长约 4.5 米、厚逾 1 米的门楣巨石，门楣上方再设减重三角石——这套承重设计让大门扛住了三千年的地震与战乱。门宽约 2.9 米，足够战车通行。',
