          '它的故事还被写进一切考古学导论：如何用出土物反证史诗、如何警惕发掘者的浪漫、如何区分「发现」与「命名」。谢里曼的电报错了，但他让世界知道了青铜时代的希腊——这张认错的脸，仍然是那个时代最清晰的脸。',
