      '一面墙，六吨琥珀，镶着玉石与镜子，烛光一照满室金红——18 世纪的欧洲人管它叫「世界第八大奇迹」。它是普鲁士国王送给俄国沙皇的国礼，装在圣彼得堡的行宫里两百年；1945 年初，纳粹把它拆进木箱运往德国，此后再无人见过。一件重达六吨的房间，在二十世纪众目睽睽之下失踪了。',
