        heading: '它是什么：一间琥珀装的房间',
        paragraphs: [
          '1701 至 1709 年，普鲁士工匠在柏林宫中造出琥珀厅：琥珀板经加温软化与蜂蜜、亚麻油染色，拼出普鲁士纹章、风景与君主像，配佛罗伦萨马赛克与鎏金雕饰。1716 年，普鲁士「士兵王」把它整墙赠予俄国彼得大帝，换取五十五名高个子卫兵——国礼史上最奢侈的一次以物易物。',
          '琥珀厅在圣彼得堡不断扩建：伊丽莎白女皇把它装进皇村（今普希金城）的叶卡捷琳娜宫，面积扩至约 55 平方米；琥珀在烛光里通透如蜜，在射灯下泛出深红。琥珀自古就是珍品——老普林尼记载过「一件小雕像卖得比活人还贵」的行情，而这间房用了整整六吨。',
        ],
