          '此后七十余年，搜寻从未停止：探矿队掘过矿井，猎人挖过湖底，赏金传闻屡屡出现又屡屡破灭；相关失踪与死亡案件给悬案添上黑色注脚。唯一确定的是：原物再未出现。2003 年，俄罗斯工匠依据旧照片与档案，用三十年时间重建琥珀厅，在叶卡捷琳娜宫开幕——复制品比原件大，细节仍据旧照逐板还原。',
