          '之后是七十多年的寻找：有人说它沉在波罗的海的沉船里，有人说它被埋在矿井或地下工事，1945 年柯尼斯堡城堡坍塌的废墟被苏军夷平时，可能连它一起被埋进了地基。 searches 一轮接一轮，悬赏一度开到数百万美元，伪造者甚至做赝品骗赏。多数学者今天的判断趋于冷静：它在 1944 年的大火中大概率已经损毁——但只要没有实物证据，琥珀宫就仍是「可能还在某处」。',
