          '「本草」是中国药物学的传统文体，历代增补至《证类本草》已达千余种药。李时珍发现旧本草名实混淆、正误相袭——有的药被张冠李戴上千年，误服可死人。他决意重修，方法只有一条：能亲自看的绝不抄书，亲自验的才敢下笔。',
          '《本草纲目》打破沿用千年的上中下三品旧例，按「从微至巨、从贱至贵」重排宇宙：矿物、植物、动物分十六部六十类——水、火、土、金石、草、谷、菜、果、木、服器、虫、鳞、介、禽、兽、人。这不是药柜的排序，是给整个自然界重新编目。',
