          '迦叶波心中有鬼：弟弟随时可能带兵回来。他没有留在旧都阿努拉德普勒——那里有旧贵族与佛教僧团的敌意——而是选中这块两百米高的独石，把自己举到天上：岩顶建宫殿，岩腹砌狮子门，四周挖三重护城河与壕沟。整座山被改造成要塞。',
