          '梦殿（739 年建）八角形仓中供奉「救世观音」秘佛，1884 年费诺罗萨与冈仓天心强行开帐，飞鸟时代的鎏金木像重见天日——秘佛传统由此轰动世界。寺中藏品被指定为日本国宝的就有约一百九十件，密度冠绝全日，一寺之内几乎是一部具象的东亚佛教美术史。',
