          '1980 年代作家水上勉也写了《五番町夕雾楼》与《金阁炎上》处理同一案件。一栋建筑的两次「成名」——一次靠金箔，一次靠纵火——说明它的故事早已超出建筑本身：美如何折磨不配拥有美的人，是这栋楼最持久的展品，展签上写着两个年份：1397 年建成，1950 年焚毁。',
