          '1994 年金阁寺作为「古都京都文化财」列入世界遗产。今天它是京都游客量的顶级名片：镜湖池畔的最佳机位终日排着长队，四季晨昏各有金影。游客看到的金阁是 1955 年的「复制品」，但没有人觉得它假——建筑的生命由使用者共同续写，这是日本「修繕」传统的又一例证。',
          '三岛在小说里写下的哲学追问至今未过时：美是安慰还是压迫？林养贤的纵火案作为真实事件，与小说互为镜像——一个用现实追问美，一个用文学回答美。金阁寺因此拥有双重遗产：一栋贴金的三层楼阁，和一部关于「为什么要烧掉它」的杰作。两份遗产都活着，且互相引用。',
          '围绕它的制度细节也很有趣：今天寺方禁止用三脚架与无人机拍摄，理由不是防偷拍，而是保护镜湖池畔的苔藓与水质——一座被写进小说的建筑，如今被写进景区管理守则。美的威胁者换了模样，守护的逻辑倒是一脉相承：美需要被观看，更需要被看住——被看住的美，才有资格继续被人看。',
