          '它的意义还在方法论上：文物保护的最高境界不是修复，而是「从第一天起就好好保管」。榫卯仓房、世代守护、克制展出——正仓院用一千二百六十年示范了什么叫「与时间合作」。长安的月亮照过这些器物，如今它们在奈良替那个时代继续存在。保护的最深技艺，是把守护本身也一并守护下去——守护制度千年的稳定运转，比守护任何一件宝物都更难，也更了不起。',
