        heading: '工艺：一座瓶形塔的天文学',
        paragraphs: [
          '瞻星台由约三百六十六块花岗岩干砌而成（一说三百六十二块，因年代风化计数不一），分二十七层，总高约九点二米。民间与学界的传统解读：石块数对应一年的日数，二十七层或与月相节气相关；顶部的方形窗口是观测与采光口。',
          '它的真实用途学界仍有争论：主流观点认为用于天文观测——观测者立于顶台，通过窗口记录星辰方位与太阳影长；也有假说认为它用于祈雨仪式或象征王权。无论哪种，它在建筑学上的价值无可争议：干砌石塔千年不倒，重心与咬合的设计至今被工程学界引用。',
          '与它同代的观测记录为后来者铺路：新罗天文学家从此参与唐朝历法的修订与校验，统一新罗时期的天文图、漏刻与星象碑延续传统——瞻星台是这条科学生命线的第一块基石。',
        ],
