          '在科学史上，它填补了一个空白：古代东亚的天文台极少有实物存世——中国的观星台多为宋元以后重修，瞻星台以七世纪的原始主体直接站在那里，成为比较文明史的难得样本：同时期的欧洲尚在中世纪早期，阿拉伯天文学还未兴起。',
