      '1811年，英军勘测队在爪哇中部的丛林里拨开藤蔓，撞见一片倒塌的尖塔森林：两百多座石庙大部分埋在火山灰与红土之下，主塔高四十七米，塔壁上刻满罗摩与神猴的战争。这就是普兰巴南——爪哇岛最大的印度教庙群，落成时曾是赤道以南最辉煌的建筑之一。它只繁荣了百余年，随后被自己的火山与丛林合谋掩埋了八百年。神话刻在石头上，比王朝活得久。',
