          '九世纪中叶，中爪哇的统治者拉卡伊·皮卡丹迎娶夏连特拉王室的公主波罗摩达瓦德哈尼——旧说这是印度教与佛教两大王朝的联姻，今有学者认为不过是同一家族的两派信仰。无论哪种解释，结果都一样：856年的《希瓦格拉哈铭文》记载了截流改道、开凿圣泉的水利工程，以及一座湿婆像落成的盛大灌顶仪式。普兰巴南的核心，就在这片新整理出的土地上拔地而起。',
          '庙群按曼荼罗布局：正中是四十七米高的湿婆神庙，南北两侧是三十三米的毗湿奴庙与梵天庙，前面对应三座坐骑庙，外围一圈两百二十四座小祠，全盛时共有庙宇约两百四十座。塔形如穗、层层收尖，是爪哇人对圣山梅鲁的想象。湿婆庙四面各辟一龛：正龛湿婆，侧龛象头神、难近母与仙人阿迦斯塔——国王把所奉诸神编成了一整套权力秩序。',
