          '传说也跟着石头生长。爪哇民间讲，力士万隆·邦多沃索要娶公主罗罗·钟格兰，公主要求他一夜建成一千座庙；神鬼通宵搬运，公主装鸡叫骗天亮，只留下九百九十九座。暴怒的王子把她变成第一千座庙——传说指认的正是湿婆庙北龛那尊难近母像。今天人们仍说雕像眉目哀婉，正是公主回望故乡的神情。神话为文物补上了史书不载的温度。',
