          '1811年重新现身后，命运并未立刻好转：殖民时代的「发掘」伴着盗凿与流散，雕像进了欧洲与雅加达的博物馆。真正的修复从1918年才开始，湿婆庙的复原直到1953年才完成——面对两百多座倒塌庙宇的上万块构件，工程师逐块编号归位，像在拼一副几百万片的拼图。今天看到的尖塔森林，一半是九世纪的石头，一半是二十世纪的耐心。',
