          '但普兰巴南早已学会与神话共生。自1961年起，露天舞台定期上演罗摩耶那芭蕾，舞者以神庙立面为布景，演的正是墙上浮雕的情节；1991年，庙群列入世界遗产。白天它是考古遗址，夜里它是剧场——石头上凝固的史诗，与活人身体里的史诗，隔着一千两百年互相注解。',
