      '1232年，蒙古铁骑第二次蹂躏高丽，都城开京陷落火海，半个世纪前为抗契丹刻成的第一部大藏经，与藏经的符仁寺一起化为灰烬。退守江华岛的高丽朝廷做了一个近乎固执的决定：重新刻一部。此后十六年，在战火最烈的年代里，僧俗刻刀昼夜不停，刻出八万一千余块经版——不是兵器，却成了这个王朝全部的精神防线。八万块木头，至今一字未磨平。',
