          '迁往江华岛的朝廷与执政的崔怡再度发愿。1236年，第二代大藏经在江华岛开雕，国王、太子、百官与百姓争相施财、写经题名；据载文豪李奎报曾为此撰写祈告文，把退敌之愿一字一句写进佛前。刻经由此成了一场持续十六年的国家总动员：不设工期，不问战局，只管刻下去。',
