          '刻印之外，流通也在继续：按传统仪轨，僧人沐手焚香后才能上版印刷，印出的经卷被各国图书馆与研究所视为顶级文献。从江华岛的海风到海印寺的山风，八万块木头走过了蒙古人、战火与数码时代，一个字都没有老，一部经书就这样替整个文明记住了自己的样子。',
